def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []

    # Sort intervals by start time
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]

    for interval in intervals[1:]:
        last = merged[-1]
        # If the current interval overlaps or touches the last merged interval
        if interval[0] <= last[1]:
            # Merge them by updating the end time
            last[1] = max(last[1], interval[1])
        else:
            merged.append(interval)

    return merged

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []

    # Sort by start time
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]

    for current in intervals[1:]:
        last = merged[-1]
        # If the current interval overlaps or touches the last merged interval
        if current[0] <= last[1]:
            # Merge them by updating the end of the last interval
            last[1] = max(last[1], current[1])
        else:
            # No overlap, add the current interval as a new merged interval
            merged.append(current)

    return merged

def flatten(obj, sep='.') -> dict:
    """
    Flattens a nested dict/list structure into a single-level dict.

    Nested dict keys are joined with `sep`.
    List elements use their index as a key component.
    Scalars at the top level of a dict stay as-is.

    Args:
        obj: The object to flatten (dict, list, or scalar).
        sep: The separator to use for joining nested keys.

    Returns:
        A flattened dictionary.
    """
    result = {}

    if isinstance(obj, dict):
        for key, value in obj.items():
            if isinstance(value, (dict, list)):
                # Recursively flatten nested structures
                nested = flatten(value, sep)
                for nested_key, nested_value in nested.items():
                    new_key = f"{key}{sep}{nested_key}"
                    result[new_key] = nested_value
            else:
                # Scalar value at this level
                result[key] = value
    elif isinstance(obj, list):
        for index, value in enumerate(obj):
            if isinstance(value, (dict, list)):
                # Recursively flatten nested structures
                nested = flatten(value, sep)
                for nested_key, nested_value in nested.items():
                    new_key = f"{index}{sep}{nested_key}"
                    result[new_key] = nested_value
            else:
                # Scalar value at this level
                result[index] = value
    else:
        # Scalar at top level - shouldn't happen in normal usage but handle it
        # Actually, if obj is a scalar, we can't really flatten it meaningfully
        # The function expects a dict or list as root
        pass

    return result

import functools


def retry(times: int, exceptions=(Exception,)):
    """Decorator factory that retries the wrapped function up to `times` total attempts when it raises one of `exceptions`.

    Args:
        times: Maximum number of attempts (including the first one).
        exceptions: Tuple of exception types to catch and retry on.

    Returns:
        A decorator that wraps the function with retry logic.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None
            for attempt in range(times):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_exception = e
            # All attempts failed, re-raise the last exception
            raise last_exception
        return wrapper
    return decorator

