from typing import Set


def ladder_length(begin: str, end: str, words: list[str]) -> int:
    word_set: Set[str] = set(words)

    # If end is not in words, impossible
    if end not in word_set:
        return 0

    # BFS
    queue = deque([(begin, 1)])
    visited = {begin}

    while queue:
        current_word, length = queue.popleft()

        if current_word == end:
            return length

        # Try changing each character
        for i in range(len(current_word)):
            for char_code in range(ord('a'), ord('z') + 1):
                new_char = chr(char_code)
                new_word = current_word[:i] + new_char + current_word[i+1:]

                if new_word not in visited and new_word in word_set:
                    if new_word == end:
                        return length + 1
                    visited.add(new_word)
                    queue.append((new_word, length + 1))

    return 0

from collections import deque

def ladder_length(begin: str, end: str, words: list[str]) -> int:
    word_set = set(words)
    if end not in word_set:
        return 0

    # BFS
    queue = deque([(begin, 1)])  # (current_word, length)
    visited = {begin}

    while queue:
        current_word, length = queue.popleft()

        if current_word == end:
            return length

        # Try changing each character
        for i in range(len(current_word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if c == current_word[i]:
                    continue
                next_word = current_word[:i] + c + current_word[i+1:]
                if next_word in word_set and next_word not in visited:
                    if next_word == end:
                        return length + 1
                    visited.add(next_word)
                    queue.append((next_word, length + 1))

    return 0

def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression string supporting +, -, *, /, parentheses,
    unary minus, integers and decimals, with correct precedence.
    Does NOT use eval/exec. Raises ValueError on malformed input.
    """
    # Tokenizer
    def tokenize(expression: str):
        tokens = []
        i = 0
        s = expression
        n = len(s)
        while i < n:
            c = s[i]
            if c in ' \t\n\r':
                i += 1
                continue
            if c in '+-*/()':
                tokens.append(c)
                i += 1
            elif c.isdigit() or c == '.':
                j = i
                has_dot = False
                while j < n and (s[j].isdigit() or s[j] == '.'):
                    if s[j] == '.':
                        if has_dot:
                            raise ValueError(f"Invalid number: {s[i:j+1]}")
                        has_dot = True
                    j += 1
                num_str = s[i:j]
                try:
                    if has_dot:
                        tokens.append(float(num_str))
                    else:
                        tokens.append(int(num_str))
                except ValueError:
                    raise ValueError(f"Invalid number: {num_str}")
                i = j
            else:
                raise ValueError(f"Unexpected character: {c}")
        return tokens

    tokens = tokenize(expr)

    # Parser using recursive descent
    # Grammar:
    # expr     -> term (('+' | '-') term)*
    # term     -> factor (('*' | '/') factor)*
    # factor   -> ('-' factor) | '(' expr ')' | number

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def consume(self):
            tok = self.tokens[self.pos]
            self.pos += 1
            return tok

        def parse(self):
            result = self.parse_expr()
            if self.pos != len(self.tokens):
                raise ValueError(f"Unexpected token: {self.tokens[self.pos]}")
            return result

        def parse_expr(self):
            """expr -> term (('+' | '-') term)*"""
            result = self.parse_term()
            while self.peek() in ('+', '-'):
                op = self.consume()
                right = self.parse_term()
                if op == '+':
                    result = result + right
                else:
                    result = result - right
            return result

        def parse_term(self):
            """term -> factor (('*' | '/') factor)*"""
            result = self.parse_factor()
            while self.peek() in ('*', '/'):
                op = self.consume()
                right = self.parse_factor()
                if op == '*':
                    result = result * right
                else:
                    if right == 0:
                        raise ValueError("Division by zero")
                    result = result / right
            return result

        def parse_factor(self):
            """factor -> ('-' factor) | '(' expr ')' | number"""
            tok = self.peek()

            # Unary minus
            if tok == '-':
                self.consume()
                operand = self.parse_factor()
                return -operand

            # Unary plus (optional, but let's handle it)
            if tok == '+':
                self.consume()
                return self.parse_factor()

            # Parenthesized expression
            if tok == '(':
                self.consume()  # consume '('
                result = self.parse_expr()
                if self.peek() != ')':
                    raise ValueError(f"Expected ')', got {self.peek()}")
                self.consume()  # consume ')'
                return result

            # Number
            if isinstance(tok, (int, float)):
                self.consume()
                return float(tok)

            raise ValueError(f"Unexpected token: {tok}")

    parser = Parser(tokens)
    return parser.parse()

class SlidingWindowRateLimiter:
    def __init__(self, max_calls: int, window: float):
        self.max_calls = max_calls
        self.window = window
        self.calls = {}  # key -> list of timestamps

    def allow(self, key: str, now: float) -> bool:
        if key not in self.calls:
            self.calls[key] = []

        # Remove calls that are outside the window
        cutoff = now - self.window
        # Keep only calls that are strictly within the window (i.e., > cutoff)
        # "calls exactly window old have expired" means calls at time (now - window) are expired
        # So we keep calls with timestamp > now - window
        self.calls[key] = [t for t in self.calls[key] if t > cutoff]

        if len(self.calls[key]) < self.max_calls:
            self.calls[key].append(now)
            return True
        else:
            return False

