def run_query(sql: str, rows: list[dict]) -> list[dict]:
    """
    Evaluate a tiny SQL SELECT over rows.
    Grammar: SELECT (* | col [AS alias] [, ...]) FROM t [WHERE cond] [ORDER BY col [ASC|DESC] [, ...]] [LIMIT n]
    """
    # Tokenize
    tokens = tokenize(sql)

    # Parse
    try:
        parsed = parse_select(tokens)
    except Exception as e:
        raise ValueError(f"Parse error: {e}") from e

    # Execute
    return execute(parsed, rows)


def tokenize(sql: str) -> list:
    """Tokenize SQL string into tokens."""
    tokens = []
    i = 0
    while i < len(sql):
        # Skip whitespace
        if sql[i].isspace():
            i += 1
            continue

        # String literal
        if sql[i] == "'":
            j = i + 1
            s = ""
            while j < len(sql) and sql[j] != "'":
                if sql[j] == '\\' and j + 1 < len(sql):
                    s += sql[j + 1]
                    j += 2
                else:
                    s += sql[j]
                    j += 1
            if j >= len(sql):
                raise ValueError("Unterminated string literal")
            tokens.append(('STRING', s))
            i = j + 1
            continue

        # Operators and punctuation
        if sql[i] in ('=', '!', '<', '>', ',', '(', ')', '*'):
            if sql[i] == '!' and i + 1 < len(sql) and sql[i + 1] == '=':
                tokens.append(('OP', '!='))
                i += 2
                continue
            if sql[i] == '<' and i + 1 < len(sql) and sql[i + 1] == '=':
                tokens.append(('OP', '<='))
                i += 2
                continue
            if sql[i] == '>' and i + 1 < len(sql) and sql[i + 1] == '=':
                tokens.append(('OP', '>='))
                i += 2
                continue
            tokens.append(('OP', sql[i]))
            i += 1
            continue

        # Numbers (int or float)
        if sql[i].isdigit() or (sql[i] == '-' and i + 1 < len(sql) and sql[i + 1].isdigit()):
            j = i
            if sql[j] == '-':
                j += 1
            while j < len(sql) and sql[j].isdigit():
                j += 1
            if j < len(sql) and sql[j] == '.':
                j += 1
                while j < len(sql) and sql[j].isdigit():
                    j += 1
                tokens.append(('NUMBER', float(sql[i:j])))
            else:
                tokens.append(('NUMBER', int(sql[i:j])))
            i = j
            continue

        # Identifiers and keywords
        if sql[i].isalpha() or sql[i] == '_':
            j = i
            while j < len(sql) and (sql[j].isalnum() or sql[j] == '_'):
                j += 1
            word = sql[i:j]
            # Check if it's a keyword
            upper = word.upper()
            if upper in ('SELECT', 'FROM', 'WHERE', 'ORDER', 'BY', 'LIMIT', 'ASC', 'DESC', 'AND', 'OR'):
                tokens.append(('KEYWORD', upper))
            else:
                tokens.append(('IDENT', word))
            i = j
            continue

        raise ValueError(f"Unexpected character: {sql[i]}")

    return tokens


class Parser:
    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Optional[Tuple[str, Any]]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected_type: Optional[str] = None, expected_value: Optional[str] = None) -> Tuple[str, Any]:
        token = self.peek()
        if token is None:
            raise ValueError(f"Unexpected end of input, expected {expected_type} {expected_value}")
        if expected_type and token[0] != expected_type:
            raise ValueError(f"Expected {expected_type}, got {token[0]}")
        if expected_value and token[1] != expected_value:
            raise ValueError(f"Expected {expected_value}, got {token[1]}")
        self.pos += 1
        return token

    def match(self, expected_type: str, expected_value: Optional[str] = None) -> bool:
        token = self.peek()
        if token is None:
            return False
        if token[0] != expected_type:
            return False
        if expected_value and token[1] != expected_value:
            return False
        return True

    def parse_select(self) -> dict:
        """Parse: SELECT (* | col [AS alias] [, ...]) FROM t [WHERE cond] [ORDER BY col [ASC|DESC] [, ...]] [LIMIT n]"""
        self.consume('KEYWORD', 'SELECT')

        # Parse selected columns
        selected = self.parse_select_columns()

        self.consume('KEYWORD', 'FROM')
        # Skip table name (identifier)
        self.consume('IDENT')

        result = {
            'selected': selected,
            'where': None,
            'order_by': [],
            'limit': None
        }

        # Optional WHERE
        if self.match('KEYWORD', 'WHERE'):
            self.consume('KEYWORD', 'WHERE')
            result['where'] = self.parse_condition()

        # Optional ORDER BY
        if self.match('KEYWORD', 'ORDER'):
            self.consume('KEYWORD', 'ORDER')
            self.consume('KEYWORD', 'BY')
            result['order_by'] = self.parse_order_by()

        # Optional LIMIT
        if self.match('KEYWORD', 'LIMIT'):
            self.consume('KEYWORD', 'LIMIT')
            token = self.consume('NUMBER')
            result['limit'] = int(token[1])

        # Check if there are remaining tokens
        if self.pos < len(self.tokens):
            raise ValueError(f"Unexpected tokens after query: {self.tokens[self.pos:]}")

        return result

    def parse_select_columns(self) -> list:
        """Parse: (* | col [AS alias] [, ...])"""
        columns = []

        if self.match('OP', '*'):
            self.consume('OP', '*')
            columns.append({'type': 'star'})
        else:
            columns.append(self.parse_select_column())

        while self.match('OP', ','):
            self.consume('OP', ',')
            columns.append(self.parse_select_column())

        return columns

    def parse_select_column(self) -> dict:
        """Parse: col [AS alias]"""
        token = self.consume('IDENT')
        col_name = token[1]
        alias = None

        if self.match('KEYWORD', 'AS'):
            self.consume('KEYWORD', 'AS')
            token = self.consume('IDENT')
            alias = token[1]

        return {'type': 'column', 'name': col_name, 'alias': alias}

    def parse_condition(self) -> dict:
        """Parse condition with AND/OR precedence. AND binds tighter than OR."""
        left = self.parse_and_condition()

        while self.match('KEYWORD', 'OR'):
            self.consume('KEYWORD', 'OR')
            right = self.parse_and_condition()
            left = {'type': 'or', 'left': left, 'right': right}

        return left

    def parse_and_condition(self) -> dict:
        """Parse AND conditions."""
        left = self.parse_primary_condition()

        while self.match('KEYWORD', 'AND'):
            self.consume('KEYWORD', 'AND')
            right = self.parse_primary_condition()
            left = {'type': 'and', 'left': left, 'right': right}

        return left

    def parse_primary_condition(self) -> dict:
        """Parse a primary condition or parenthesized expression."""
        if self.match('OP', '('):
            self.consume('OP', '(')
            cond = self.parse_condition()
            self.consume('OP', ')')
            return cond

        # Parse comparison: col = value
        left_token = self.consume('IDENT')
        left_name = left_token[1]

        op_token = self.consume('OP')
        op = op_token[1]

        right_token = self.consume('NUMBER', 'STRING')
        if right_token[0] == 'NUMBER':
            right_value = right_token[1]
        else:
            right_value = right_token[1]

        return {'type': 'compare', 'col': left_name, 'op': op, 'value': right_value}

    def parse_order_by(self) -> list:
        """Parse: col [ASC|DESC] [, ...]"""
        order_by = []

        token = self.consume('IDENT')
        col = token[1]
        direction = 'ASC'

        if self.match('KEYWORD', 'ASC'):
            self.consume('KEYWORD', 'ASC')
            direction = 'ASC'
        elif self.match('KEYWORD', 'DESC'):
            self.consume('KEYWORD', 'DESC')
            direction = 'DESC'

        order_by.append({'col': col, 'direction': direction})

        while self.match('OP', ','):
            self.consume('OP', ',')
            token = self.consume('IDENT')
            col = token[1]
            direction = 'ASC'

            if self.match('KEYWORD', 'ASC'):
                self.consume('KEYWORD', 'ASC')
                direction = 'ASC'
            elif self.match('KEYWORD', 'DESC'):
                self.consume('KEYWORD', 'DESC')
                direction = 'DESC'

            order_by.append({'col': col, 'direction': direction})

        return order_by


def parse_select(tokens: list) -> dict:
    parser = Parser(tokens)
    return parser.parse_select()


def evaluate_condition(cond: dict, row: dict) -> bool:
    """Evaluate a condition against a row."""
    if cond['type'] == 'and':
        return evaluate_condition(cond['left'], row) and evaluate_condition(cond['right'], row)
    elif cond['type'] == 'or':
        return evaluate_condition(cond['left'], row) or evaluate_condition(cond['right'], row)
    elif cond['type'] == 'compare':
        col = cond['col']
        op = cond['op']
        value = cond['value']

        if col not in row:
            return False

        row_val = row[col]

        # Handle type coercion for comparison
        if isinstance(row_val, str) and isinstance(value, (int, float)):
            try:
                row_val = float(row_val)
            except (ValueError, TypeError):
                return False
        elif isinstance(row_val, (int, float)) and isinstance(value, str):
            try:
                value = float(value)
            except (ValueError, TypeError):
                return False

        if op == '=':
            return row_val == value
        elif op == '!=':
            return row_val != value
        elif op == '<':
            return row_val < value
        elif op == '<=':
            return row_val <= value
        elif op == '>':
            return row_val > value
        elif op == '>=':
            return row_val >= value
        else:
            raise ValueError(f"Unknown operator: {op}")
    else:
        raise ValueError(f"Unknown condition type: {cond['type']}")


def execute(parsed: dict, rows: list[dict]) -> list[dict]:
    """Execute the parsed query against rows."""
    selected = parsed['selected']
    where = parsed['where']
    order_by = parsed['order_by']
    limit = parsed['limit']

    # Filter rows
    if where:
        filtered = [row for row in rows if evaluate_condition(where, row)]
    else:
        filtered = list(rows)

    # Select columns
    result = []
    for row in filtered:
        new_row = {}
        for col_spec in selected:
            if col_spec['type'] == 'star':
                # Include all columns
                for k, v in row.items():
                    new_row[k] = v
            elif col_spec['type'] == 'column':
                col_name = col_spec['name']
                alias = col_spec['alias'] if col_spec['alias'] else col_name
                if col_name in row:
                    new_row[alias] = row[col_name]
                else:
                    # Column not in row, skip or use None? Let's skip for now
                    pass
        result.append(new_row)

    # Order by
    if order_by:
        def sort_key(row):
            keys = []
            for spec in order_by:
                col = spec['col']
                direction = spec['direction']
                if col in row:
                    val = row[col]
                    # Handle None values
                    if val is None:
                        # Put None at the end for ASC, beginning for DESC
                        if direction == 'ASC':
                            keys.append((1, 0, ''))
                        else:
                            keys.append((0, 0, ''))
                    else:
                        if direction == 'ASC':
                            keys.append((0, val, ''))
                        else:
                            keys.append((1, val, ''))
                else:
                    if direction == 'ASC':
                        keys.append((1, 0, ''))
                    else:
                        keys.append((0, 0, ''))
            return keys

        # Stable sort
        for spec in reversed(order_by):
            col = spec['col']
            direction = spec['direction']
            reverse = (direction == 'DESC')

            def make_key(c, r):
                def key_func(row):
                    if c in row:
                        val = row[c]
                        if val is None:
                            return (1,)
                        return (0, val)
                    else:
                        return (1,)
                return key_func

            result.sort(key=make_key(col, reverse), reverse=reverse)

    # Limit
    if limit is not None:
        result = result[:limit]

    return result

import re
from typing import Any


def run_query(sql: str, rows: list[dict]) -> list[dict]:
    """
    Evaluate a tiny SQL SELECT over rows.

    Grammar: SELECT (* | col [AS alias] [, ...]) FROM t [WHERE cond] [ORDER BY col [ASC|DESC] [, ...]] [LIMIT n]

    Conditions support comparisons =, !=, <, <=, >, >= against integer, float or single-quoted string literals,
    combined with AND / OR and grouped with parentheses; AND binds tighter than OR.
    Keywords are case-insensitive, column names are case-sensitive.
    The FROM table name is ignored.
    Output dicts contain only the selected columns, keyed by alias when given, in the order they were selected.
    Raise ValueError on a parse error.
    """
    # Tokenize
    tokens = tokenize(sql)
    if not tokens:
        raise ValueError("Empty SQL")

    # Parse
    parser = Parser(tokens)
    result = parser.parse_select()
    return result


class Token:
    def __init__(self, type_: str, value: Any):
        self.type = type_
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value!r})"


def tokenize(sql: str) -> list[Token]:
    """Tokenize the SQL string."""
    tokens = []
    i = 0
    n = len(sql)

    while i < n:
        # Skip whitespace
        if sql[i].isspace():
            i += 1
            continue

        # Check for operators: !=, <=, >=, <, >, =
        if sql[i:i+2] in ('!=', '<=', '>='):
            tokens.append(Token('OP', sql[i:i+2]))
            i += 2
            continue

        if sql[i] in ('<', '>', '='):
            tokens.append(Token('OP', sql[i]))
            i += 1
            continue

        # Check for comma, parentheses, asterisk
        if sql[i] == ',':
            tokens.append(Token('COMMA', ','))
            i += 1
            continue
        if sql[i] == '(':
            tokens.append(Token('LPAREN', '('))
            i += 1
            continue
        if sql[i] == ')':
            tokens.append(Token('RPAREN', ')'))
            i += 1
            continue
        if sql[i] == '*':
            tokens.append(Token('STAR', '*'))
            i += 1
            continue

        # Single-quoted string
        if sql[i] == "'":
            j = i + 1
            while j < n and sql[j] != "'":
                if sql[j] == '\\' and j + 1 < n:
                    j += 2
                else:
                    j += 1
            if j >= n:
                raise ValueError(f"Unterminated string at position {i}")
            # j is at the closing quote
            string_val = sql[i+1:j]
            # Handle escapes
            string_val = string_val.replace("\\'", "'")
            tokens.append(Token('STRING', string_val))
            i = j + 1
            continue

        # Number (integer or float)
        if sql[i].isdigit() or (sql[i] == '-' and i + 1 < n and sql[i+1].isdigit()):
            j = i
            if sql[j] == '-':
                j += 1
            while j < n and sql[j].isdigit():
                j += 1
            if j < n and sql[j] == '.':
                j += 1
                while j < n and sql[j].isdigit():
                    j += 1
                num_val = float(sql[i:j])
            else:
                num_val = int(sql[i:j])
            tokens.append(Token('NUMBER', num_val))
            i = j
            continue

        # Identifier or keyword
        if sql[i].isalpha() or sql[i] == '_':
            j = i
            while j < n and (sql[j].isalnum() or sql[j] == '_'):
                j += 1
            word = sql[i:j]
            upper = word.upper()
            if upper in ('SELECT', 'FROM', 'WHERE', 'ORDER', 'BY', 'ASC', 'DESC', 'LIMIT', 'AND', 'OR'):
                tokens.append(Token('KEYWORD', upper))
            else:
                tokens.append(Token('IDENT', word))
            i = j
            continue

        raise ValueError(f"Unexpected character '{sql[i]}' at position {i}")

    return tokens


class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return Token('EOF', None)

    def consume(self, expected_type: str = None, expected_value: Any = None) -> Token:
        token = self.peek()
        if expected_type and token.type != expected_type:
            raise ValueError(f"Expected {expected_type}, got {token.type} ({token.value!r})")
        if expected_value and token.value != expected_value:
            raise ValueError(f"Expected {expected_value!r}, got {token.value!r}")
        self.pos += 1
        return token

    def expect_keyword(self, kw: str):
        token = self.consume('KEYWORD', kw)
        return token

    def at_end(self) -> bool:
        return self.pos >= len(self.tokens)

    def parse_select(self) -> list[dict]:
        """Parse: SELECT (* | col [AS alias] [, ...]) FROM t [WHERE cond] [ORDER BY col [ASC|DESC] [, ...]] [LIMIT n]"""
        # SELECT
        self.expect_keyword('SELECT')

        # Parse column list
        columns, aliases = self.parse_select_columns()

        # FROM
        self.expect_keyword('FROM')
        # Table name - skip it
        table_token = self.consume('IDENT')
        # Could also be a keyword if table name is a keyword, but we'll just consume an identifier

        # WHERE
        where_clause = None
        if self.peek().type == 'KEYWORD' and self.peek().value == 'WHERE':
            self.consume('KEYWORD', 'WHERE')
            where_clause = self.parse_condition()

        # ORDER BY
        order_by = []
        if self.peek().type == 'KEYWORD' and self.peek().value == 'ORDER':
            self.consume('KEYWORD', 'ORDER')
            self.consume('KEYWORD', 'BY')
            order_by = self.parse_order_by()

        # LIMIT
        limit = None
        if self.peek().type == 'KEYWORD' and self.peek().value == 'LIMIT':
            self.consume('KEYWORD', 'LIMIT')
            num_token = self.consume('NUMBER')
            limit = int(num_token.value)

        # Process the query
        result = self.execute_select(columns, aliases, where_clause, order_by, limit, rows)
        return result

    def parse_select_columns(self) -> tuple[list[str], list[str]]:
        """Parse column list: (* | col [AS alias] [, ...])"""
        columns = []
        aliases = []

        if self.peek().type == 'STAR':
            self.consume('STAR')
            return ['*'], ['*']

        # First column
        col_token = self.consume('IDENT')
        col_name = col_token.value
        alias = col_name

        if self.peek().type == 'KEYWORD' and self.peek().value == 'AS':
            self.consume('KEYWORD', 'AS')
            alias_token = self.consume('IDENT')
            alias = alias_token.value

        columns.append(col_name)
        aliases.append(alias)

        # More columns?
        while self.peek().type == 'COMMA':
            self.consume('COMMA')
            col_token = self.consume('IDENT')
            col_name = col_token.value
            alias = col_name

            if self.peek().type == 'KEYWORD' and self.peek().value == 'AS':
                self.consume('KEYWORD', 'AS')
                alias_token = self.consume('IDENT')
                alias = alias_token.value

            columns.append(col_name)
            aliases.append(alias)

        return columns, aliases

    def parse_order_by(self) -> list[tuple[str, str]]:
        """Parse ORDER BY clause: col [ASC|DESC] [, ...]"""
        order_by = []

        col_token = self.consume('IDENT')
        col_name = col_token.value
        direction = 'ASC'

        if self.peek().type == 'KEYWORD' and self.peek().value in ('ASC', 'DESC'):
            direction = self.consume('KEYWORD').value

        order_by.append((col_name, direction))

        while self.peek().type == 'COMMA':
            self.consume('COMMA')
            col_token = self.consume('IDENT')
            col_name = col_token.value
            direction = 'ASC'

            if self.peek().type == 'KEYWORD' and self.peek().value in ('ASC', 'DESC'):
                direction = self.consume('KEYWORD').value

            order_by.append((col_name, direction))

        return order_by

    def parse_condition(self) -> callable:
        """Parse condition: supports AND/OR with proper precedence, parentheses, comparisons."""
        # OR has lower precedence than AND
        left = self.parse_and_condition()

        while self.peek().type == 'KEYWORD' and self.peek().value == 'OR':
            self.consume('KEYWORD', 'OR')
            right = self.parse_and_condition()
            left = self.make_or(left, right)

        return left

    def parse_and_condition(self) -> callable:
        """Parse AND condition."""
        left = self.parse_primary_condition()

        while self.peek().type == 'KEYWORD' and self.peek().value == 'AND':
            self.consume('KEYWORD', 'AND')
            right = self.parse_primary_condition()
            left = self.make_and(left, right)

        return left

    def parse_primary_condition(self) -> callable:
        """Parse primary condition: comparison or parenthesized expression."""
        if self.peek().type == 'LPAREN':
            self.consume('LPAREN')
            cond = self.parse_condition()
            self.consume('RPAREN')
            return cond

        # Comparison: col OP value
        left_token = self.peek()
        if left_token.type != 'IDENT':
            raise ValueError(f"Expected column name, got {left_token.type} ({left_token.value!r})")

        col_name = self.consume('IDENT').value
        op_token = self.consume('OP')
        op = op_token.value

        right_token = self.peek()
        if right_token.type not in ('NUMBER', 'STRING'):
            raise ValueError(f"Expected number or string literal, got {right_token.type} ({right_token.value!r})")

        right_val = self.consume().value

        # Determine the type of comparison
        # We need to handle type coercion: compare as numbers if both are numeric, else as strings
        def comparator(row: dict) -> bool:
            if col_name not in row:
                return False
            left_val = row[col_name]

            # Determine comparison type based on the literal type
            if isinstance(right_val, (int, float)):
                # Try to convert left_val to number
                try:
                    left_num = float(left_val) if not isinstance(left_val, (int, float)) else left_val
                    right_num = float(right_val)
                except (ValueError, TypeError):
                    return False
                return compare_numbers(left_num, right_num, op)
            elif isinstance(right_val, str):
                # Compare as strings
                return compare_strings(str(left_val), right_val, op)
            else:
                return False

        return comparator

    def make_and(self, left: callable, right: callable) -> callable:
        return lambda row: left(row) and right(row)

    def make_or(self, left: callable, right: callable) -> callable:
        return lambda row: left(row) or right(row)


def compare_numbers(left, right, op: str) -> bool:
    if op == '=':
        return left == right
    elif op == '!=':
        return left != right
    elif op == '<':
        return left < right
    elif op == '<=':
        return left <= right
    elif op == '>':
        return left > right
    elif op == '>=':
        return left >= right
    else:
        raise ValueError(f"Unknown operator: {op}")


def compare_strings(left, right, op: str) -> bool:
    if op == '=':
        return left == right
    elif op == '!=':
        return left != right
    elif op == '<':
        return left < right
    elif op == '<=':
        return left <= right
    elif op == '>':
        return left > right
    elif op == '>=':
        return left >= right
    else:
        raise ValueError(f"Unknown operator: {op}")


class TinySQLExecutor:
    """Executor that processes parsed query components."""

    @staticmethod
    def execute_select(columns: list[str], aliases: list[str], 
                       where_clause: callable, order_by: list[tuple[str, str]], 
                       limit: int, rows: list[dict]) -> list[dict]:
        """Execute the SELECT query."""

        # Filter rows
        if where_clause:
            filtered = [row for row in rows if where_clause(row)]
        else:
            filtered = list(rows)

        # Select columns
        if columns == ['*']:
            # Return all columns
            result_rows = []
            for row in filtered:
                result_rows.append(dict(row))
        else:
            result_rows = []
            for row in filtered:
                new_row = {}
                for col, alias in zip(columns, aliases):
                    if col in row:
                        new_row[alias] = row[col]
                    else:
                        new_row[alias] = None
                result_rows.append(new_row)

        # Order by
        if order_by:
            def sort_key(row):
                keys = []
                for col, direction in order_by:
                    val = row.get(col)
                    # Handle None values - sort them first or last? Let's put them first
                    if val is None:
                        keys.append((0, ''))
                    else:
                        keys.append((1, val))
                return keys

            # We need to handle ascending/descending
            # Let's do a more sophisticated sort
            def multi_sort_key(row):
                keys = []
                for col, direction in order_by:
                    val = row.get(col)
                    if val is None:
                        # Put None at the beginning for ASC, end for DESC
                        if direction == 'ASC':
                            keys.append((0, ''))
                        else:
                            keys.append((1, ''))
                    else:
                        if direction == 'ASC':
                            keys.append((0, val))
                        else:
                            keys.append((0, val))
                return keys

            # Actually, let's use a simpler approach with functools.cmp_to_key
            from functools import cmp_to_key

            def compare_rows(a, b):
                for col, direction in order_by:
                    val_a = a.get(col)
                    val_b = b.get(col)

                    # Handle None
                    if val_a is None and val_b is None:
                        continue
                    if val_a is None:
                        return -1 if direction == 'ASC' else 1
                    if val_b is None:
                        return 1 if direction == 'ASC' else -1

                    # Compare
                    if isinstance(val_a, (int, float)) and isinstance(val_b, (int, float)):
                        cmp = (val_a > val_b) - (val_a < val_b)
                    else:
                        cmp = (str(val_a) > str(val_b)) - (str(val_a) < str(val_b))

                    if direction == 'DESC':
                        cmp = -cmp

                    if cmp != 0:
                        return cmp
                return 0

            result_rows.sort(key=cmp_to_key(compare_rows))

        # Limit
        if limit is not None:
            result_rows = result_rows[:limit]

        return result_rows


# Replace the module-level function with one that uses the executor
def run_query(sql: str, rows: list[dict]) -> list[dict]:
    """
    Evaluate a tiny SQL SELECT over rows.

    Grammar: SELECT (* | col [AS alias] [, ...]) FROM t [WHERE cond] [ORDER BY col [ASC|DESC] [, ...]] [LIMIT n]

    Conditions support comparisons =, !=, <, <=, >, >= against integer, float or single-quoted string literals,
    combined with AND / OR and grouped with parentheses; AND binds tighter than OR.
    Keywords are case-insensitive, column names are case-sensitive.
    The FROM table name is ignored.
    Output dicts contain only the selected columns, keyed by alias when given, in the order they were selected.
    Raise ValueError on a parse error.
    """
    # Tokenize
    tokens = tokenize(sql)
    if not tokens:
        raise ValueError("Empty SQL")

    # Parse
    parser = Parser(tokens)
    columns, aliases = parser.parse_select_columns()
    parser.expect_keyword('FROM')
    parser.consume('IDENT')

    where_clause = None
    if parser.peek().type == 'KEYWORD' and parser.peek().value == 'WHERE':
        parser.consume('KEYWORD', 'WHERE')
        where_clause = parser.parse_condition()

    order_by = []
    if parser.peek().type == 'KEYWORD' and parser.peek().value == 'ORDER':
        parser.consume('KEYWORD', 'ORDER')
        parser.consume('KEYWORD', 'BY')
        order_by = parser.parse_order_by()

    limit = None
    if parser.peek().type == 'KEYWORD' and parser.peek().value == 'LIMIT':
        parser.consume('KEYWORD', 'LIMIT')
        num_token = parser.consume('NUMBER')
        limit = int(num_token.value)

    return TinySQLExecutor.execute_select(columns, aliases, where_clause, order_by, limit, rows)

import heapq


class MedianStream:
    def __init__(self):
        # Max-heap for the lower half (store negative values to simulate max-heap)
        self._lower = []
        # Min-heap for the upper half
        self._upper = []
        # Track counts for lazy removal
        self._remove_lower = {}  # value -> count of pending removals
        self._remove_upper = {}  # value -> count of pending removals
        self._size = 0

    def add(self, x: float) -> None:
        # Add to appropriate heap
        if not self._lower or x <= -self._lower[0]:
            heapq.heappush(self._lower, -x)
        else:
            heapq.heappush(self._upper, x)

        self._size += 1

        # Balance heaps: lower can have at most one more than upper
        if len(self._lower) > len(self._upper) + 1:
            val = -heapq.heappop(self._lower)
            heapq.heappush(self._upper, val)
        elif len(self._upper) > len(self._lower):
            val = heapq.heappop(self._upper)
            heapq.heappush(self._lower, -val)

        # Clean up lazy removals
        self._clean_lower()
        self._clean_upper()

    def median(self) -> float:
        self._clean_lower()
        self._clean_upper()

        if self._size == 0:
            raise ValueError("Cannot compute median of empty stream")

        if self._size % 2 == 1:
            return -self._lower[0]
        else:
            return (-self._lower[0] + self._upper[0]) / 2.0

    def remove(self, x: float) -> None:
        self._clean_lower()
        self._clean_upper()

        # Check if x exists
        found = False
        if self._lower and x == -self._lower[0]:
            found = True
        elif not found and self._upper and x == self._upper[0]:
            found = True
        elif not found:
            # Search in heaps for the value
            if self._lower:
                # Check if x is in lower (need to search)
                # We need to find and remove x from the correct heap
                found = self._remove_from_heap(x)
            else:
                found = self._remove_from_heap(x)

        if not found:
            raise ValueError(f"Value {x} not found in stream")

        self._size -= 1

        # Rebalance
        self._balance()

        # Clean up
        self._clean_lower()
        self._clean_upper()

    def _remove_from_heap(self, x: float) -> bool:
        """Remove x from either heap. Returns True if found and removed."""
        # Try lower heap
        if self._lower and x == -self._lower[0]:
            heapq.heappop(self._lower)
            return True
        # Try upper heap
        if self._upper and x == self._upper[0]:
            heapq.heappop(self._upper)
            return True

        # Need to search for the value in the heap
        # For lower heap
        if self._lower:
            # Find x in lower
            found_idx = -1
            for i, val in enumerate(self._lower):
                if -val == x:
                    found_idx = i
                    break
            if found_idx != -1:
                # Remove from heap
                self._lower[found_idx] = self._lower[-1]
                self._lower.pop()
                if self._lower:
                    heapq.heapify(self._lower)
                return True

        if self._upper:
            found_idx = -1
            for i, val in enumerate(self._upper):
                if val == x:
                    found_idx = i
                    break
            if found_idx != -1:
                self._upper[found_idx] = self._upper[-1]
                self._upper.pop()
                if self._upper:
                    heapq.heapify(self._upper)
                return True

        return False

    def _balance(self):
        """Rebalance heaps after removal."""
        self._clean_lower()
        self._clean_upper()

        if len(self._lower) > len(self._upper) + 1:
            val = -heapq.heappop(self._lower)
            heapq.heappush(self._upper, val)
        elif len(self._upper) > len(self._lower):
            val = heapq.heappop(self._upper)
            heapq.heappush(self._lower, -val)

    def _clean_lower(self):
        """Remove lazy-deleted elements from the top of lower heap."""
        while self._lower:
            top = -self._lower[0]
            if top in self._remove_lower and self._remove_lower[top] > 0:
                heapq.heappop(self._lower)
                self._remove_lower[top] -= 1
                if self._remove_lower[top] == 0:
                    del self._remove_lower[top]
            else:
                break

    def _clean_upper(self):
        """Remove lazy-deleted elements from the top of upper heap."""
        while self._upper:
            top = self._upper[0]
            if top in self._remove_upper and self._remove_upper[top] > 0:
                heapq.heappop(self._upper)
                self._remove_upper[top] -= 1
                if self._remove_upper[top] == 0:
                    del self._remove_upper[top]
            else:
                break
